def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" x , 3 , 1 \n", " y , -2 , 0 ", " z , 0 , \t"]) == [
        {"id": "x", "day": 3, "converted": True},
        {"id": "y", "day": -2, "converted": False},
        {"id": "z", "day": 0, "converted": None},
    ]


def test_parse_session_log_skips_blanks_and_comments():
    lines = ["", "\n", " \t\n", "# comment", " \t# ignored, even, with, commas", "x,1,1"]
    assert parse_session_log(iter(lines)) == [{"id": "x", "day": 1, "converted": True}]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["x", "x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 5\b"):
        parse_session_log(["", " # comment", " \t", "ok,1,0", bad_line])


def test_dedupe_sessions_last_duplicate_id_wins():
    earlier = {"id": "x", "day": 10, "converted": True}
    later = {"id": "x", "day": 1, "converted": None}
    events = [earlier, {"id": "y", "day": 2, "converted": False}, later]
    assert dedupe_sessions(events) == [later, events[1]]
    assert events == [earlier, events[1], later]


def test_dedupe_sessions_sorted_by_day_then_id():
    events = [
        {"id": "a", "day": 3, "converted": True},
        {"id": "z", "day": 1, "converted": False},
        {"id": "b", "day": 3, "converted": True},
        {"id": "a", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [events[1], events[3], events[2]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = [
        {"day": 5, "converted": True},
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": False},
        {"day": 3, "converted": None},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]
